-- Restoring `NOT NULL` means writing the derived names back down.
--
-- Every null `name` is a name its address spells -- that is the whole of
-- what the null means -- so the column is filled in rather than guessed at.
-- The arithmetic is `galos_index::procedural`'s: the boxel bits of the
-- address, the code in base 26, and the sector's own name out of the
-- dictionary compiled into that crate. The dictionary is carried here
-- verbatim, all 11,662 sectors of it, because a migration cannot read the
-- index's file and a name backfilled from anything less would be a name
-- made up.
--
-- This costs what the way up saved: a pass over every unnamed row, a name
-- assembled apiece, and the text written back into the table and into both
-- name indexes. Hours on a galaxy-sized table, and unavoidable -- the bytes
-- are the point.
--
-- A null name whose sector the dictionary does not hold cannot be derived,
-- and is a row written wrongly rather than a system without a name. So this
-- stops and says how many rather than inventing names for them.

CREATE TEMPORARY TABLE sector_names (key integer PRIMARY KEY, name text NOT NULL);

-- `galos_index/data/sectors.csv` as it stands: the packed sector coordinate
-- `(x << 13) | (y << 7) | z` on the galaxy's own 1,280 ly grid, and the name
-- of the sector at it. A sector the galaxy has no name for is deliberately
-- absent, as is every one of Frontier's hand-authored regions -- which is
-- why no row under one is ever left unnamed for this to have to derive.
INSERT INTO sector_names (key, name)
SELECT split_part(line, E'\t', 1)::integer, split_part(line, E'\t', 2)
  FROM unnest(string_to_array($sectors$53162	EORLD GROA
