-- Which sector the address sits in, keyed as the dictionary keys it.
--
-- The address packs the sector's coordinates at the scale the primary
-- star's mass class implies: a boxel is `10 * 2^mass` light years across
-- and the boxel coordinates beside it take `7 - mass` bits an axis, so
-- where the sector's own bits sit moves with the class.
CREATE FUNCTION pg_temp.sector_key(address bigint) RETURNS integer
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    bits int := 7 - (address & 7)::int;
BEGIN
    RETURN ((((address >> (16 + 3 * bits)) & 127) << 13)
          | (((address >> (10 + 2 * bits)) & 63) << 7)
          | ((address >> (3 + bits)) & 127))::int;
END $$;

-- How the boxel and the system's index are spelled, after the sector.
--
-- `YE-Q D5-0`: the boxel's ordinal in base 26, then the mass class as a
-- letter, then the run of 17,576 boxels the ordinal is into, then the
-- system's own index in the boxel. A run of nought is written by being left
-- out. The ordinal is packed on a stride of 128 an axis whatever the class,
-- which is the one constant `Boxel::of` took measuring to find.
CREATE FUNCTION pg_temp.boxel_tail(address bigint) RETURNS text
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    mass int := (address & 7)::int;
    bits int := 7 - mass;
    mask bigint := (1::bigint << bits) - 1;
    ordinal bigint := (((address >> 3) & mask) * 16384)
                    + (((address >> (10 + bits)) & mask) * 128)
                    + ((address >> (16 + 2 * bits)) & mask);
    code bigint := ordinal % 17576;
    run bigint := ordinal / 17576;
    held bigint := (address >> (23 + 3 * bits)) & 4294967295;
BEGIN
    RETURN chr(65 + (code % 26)::int)
        || chr(65 + ((code / 26) % 26)::int)
        || '-'
        || chr(65 + (code / 676)::int)
        || ' '
        || chr(65 + mass)
        || CASE WHEN run = 0 THEN '' ELSE run || '-' END
        || held;
END $$;

UPDATE systems s
   SET name = d.name || ' ' || pg_temp.boxel_tail(s.address)
  FROM sector_names d
 WHERE s.name IS NULL AND d.key = pg_temp.sector_key(s.address);

DO $$
DECLARE left_over bigint;
BEGIN
    SELECT count(*) INTO left_over FROM systems WHERE name IS NULL;
    IF left_over > 0 THEN
        RAISE EXCEPTION
            '% system(s) have no name on record and no address that spells one',
            left_over;
    END IF;
END $$;

ALTER TABLE systems ALTER COLUMN name SET NOT NULL;
